+        for (int i = 0; i < 4; ++i)
+          r[j][i].load(r_row + i * kHidden, vid);
+      }
+    }
+#pragma unroll
+    for (int j = 0; j < kLoadGroup; ++j) {
+      const int v = g + j;
+      const int64_t vid = t + v * kThreadsPerRow;
+      float acc_y[8] = {};
+      if (live) {
+#pragma unroll
+        for (int o = 0; o < 4; ++o) {
+          V stream;
+          if constexpr (kWithPost) {
+#pragma unroll
+            for (int k = 0; k < 4; ++k) {
