+public:
+  using Type = std::conditional_t<kUseTma, CUtensorMap const, void *const>;
+};
+
+CUDA_INLINE const void *param_to_ptr(const CUtensorMap &x) { return &x; }
+CUDA_INLINE const void *param_to_ptr(void *const &x) { return x; }
+
+
+template <
