+  constexpr uint64_t swizzle_type = swizzle_bytes == 128 ? 1 : 2;
+  constexpr uint64_t stride = (swizzle_bytes * 8) >> 4;
+  constexpr uint64_t desc_base = (swizzle_type << 62) | (stride << 32);
